{"content": """"Reproduction for TrustedHostMiddleware wildcard-pattern validation bug."""
from starlette.applications import Starlette
from starlette.middleware.trustedhost import TrustedHostMiddleware

MSG = "Domain wildcard patterns must be like '*.example.com'."

failures = []


def check(name, fn):
    try:
        fn()
        print(f"PASS: {name}")
    except Exception as e:  # noqa: BLE001
        failures.append(name)
        print(f"FAIL: {name} -> {type(e).__name__}: {e}")


def invalid_wildcard_raises():
    """*example.com (star not followed by a dot) must raise the exact message."""
    try:
        TrustedHostMiddleware(Starlette(), allowed_hosts=["*example.com"])
    except ValueError as e:
        assert str(e) == MSG, f"wrong message: {e!r}"
        return
    raise AssertionError("expected ValueError for '*example.com'")


def valid_wildcard_accepted():
    m = TrustedHostMiddleware(Starlette(), allowed_hosts=["*.example.com"])
    assert m.allowed_hosts == ["*.example.com"]


def plain_host_accepted():
    m = TrustedHostMiddleware(Starlette(), allowed_hosts=["example.com"])
    assert m.allowed_hosts == ["example.com"]


def bare_wildcard_accepted():
    """'*' is the documented catch-all: must NOT raise."""
    m = TrustedHostMiddleware(Starlette(), allowed_hosts=["*"])
    assert m.allowed_hosts == ["*"]
    assert m.allow_any is True


def default_allowed_hosts_works():
    """Constructing with no allowed_hosts must not raise (defaults to ['*'])."""
    m = TrustedHostMiddleware(Starlette())
    assert m.allowed_hosts == ["*"]
    assert m.allow_any is True


def other_invalid_wildcards_raise():
    for bad in ("*example", "**", "*www.example.com"):
        try:
            TrustedHostMiddleware(Starlette(), allowed_hosts=[bad])
        except ValueError as e:
            assert str(e) == MSG
            continue
        raise AssertionError(f"expected ValueError for {bad!r}")


if __name__ == "__main__":
    for fn in (
        invalid_wildcard_raises,
        valid_wildcard_accepted,
        plain_host_accepted,
        bare_wildcard_accepted,
        default_allowed_hosts_works,
        other_invalid_wildcards_raise,
    ):
        check(fn.__name__, fn)
    print()
    if failures:
        print(f"{len(failures)} FAILURE(S): {failures}")
        raise SystemExit(1)
    print("ALL PASS")
